"""Individual jury organization cases, distinct counts and deadlines."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
rows={}
def add(n,s,p,a,c,v,q,t,d):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP])
add(425,'Lista anual de jurados usa faixas populacionais e pode ser ampliada quando necessário.', ['Mais de um milhão: 800–1500.', 'Mais de cem mil na faixa intermediária: 300–700.', 'Menor população: 80–400.', 'Pode haver aumento e lista de suplentes; indicação por núcleos comunitários.'], 'Não confundir lista anual com 25 sorteados ou sete no Conselho; texto usa mais de, não igual a, nos cortes populacionais.', 'Comarca de dois milhões organiza lista na faixa de 800 a 1500.', 'Lista anual não é limitada aos sete julgadores de uma causa.', ['Lista anual é o Conselho de sete? Não.', 'Número pode aumentar onde necessário? Sim.'], 'Alistamento anual','Formação do conjunto de cidadãos aptos a sorteio.')
add(426,'Lista com profissões é publicada até dez de outubro; alteração até dez de novembro, quando se torna definitiva.', ['Qualquer pessoa pode reclamar ao presidente no prazo.', 'Publicar também arts. 436–446.', 'Cartões iguais verificados com MP, OAB e Defensoria; guarda em urna fechada.', 'Excluir quem integrou Conselho nos doze meses anteriores à publicação.', 'Completar lista a cada ano.'], 'Não excluir por simplesmente ter sido convocado: §4º exige ter integrado Conselho.', 'Cidadã que participou do Conselho há seis meses é excluída da lista nas condições do §4º.', 'Convocada que não integrou Conselho não preenche esse fundamento só pela convocação.', ['Lista definitiva é publicada em dez de novembro? Sim.', 'Mera convocação equivale à participação no Conselho? Não.'], 'Lista geral','Registro anual com publicidade, atualização e controles.')
add(427,'Tribunal pode desaforar por ordem pública, dúvida de imparcialidade ou segurança do acusado, para comarca adequada da mesma região.', ['Pedido: MP, assistente, querelante, acusado; representação do juiz.', 'Preferir comarcas próximas sem os motivos.', 'Distribuição imediata e preferência; suspensão fundamentada pelo relator se razões relevantes.', 'Ouvir presidente salvo se ele solicitou.', 'Restrições: recurso de pronúncia pendente ou julgamento realizado; exceção de fato durante/após julgamento anulado.'], 'Não transferir por simples conveniência nem tratar pedido como suspensão automática.', 'Ameaça concreta à segurança do acusado fundamenta pedido ao Tribunal.', 'Relator examina relevância antes de suspender; requerimento sozinho não suspende.', ['Pedido suspende automaticamente? Não.', 'Comarca deve ser da mesma região nas condições do artigo? Sim.'], 'Desaforamento','Transferência excepcional do local do julgamento.')
add(428,'Excesso de serviço comprovado pode motivar desaforamento se julgamento não puder ocorrer em seis meses da pronúncia transitada.', ['Ouvir presidente e parte contrária.', 'Descontar adiamentos, diligências e incidentes de interesse da defesa.', 'Sem excesso nem fila além da capacidade, acusado pode pedir determinação de julgamento imediato.'], 'Não contar sempre seis meses corridos sem as exclusões nem presumir excesso.', 'Fila comprovadamente inviável leva à análise da transferência após prazo pertinente.', 'Diligência de interesse defensivo não entra automaticamente na contagem do §1º.', ['Excesso precisa ser comprovado? Sim.', 'Tempo de incidente de interesse da defesa entra sempre? Não.'], 'Desaforamento por demora','Medida de gestão sujeita a prazo e comprovação.')
add(429,'Pauta prefere presos, os presos há mais tempo e, em condições iguais, os pronunciados anteriormente.', ['Motivo relevante pode alterar ordem.', 'Lista publicada antes do primeiro julgamento da reunião.', 'Reservar datas para processos adiados.'], 'Preferência não dispensa motivação para exceção nem se resume à data da denúncia.', 'Dois presos em condições pertinentes são ordenados considerando tempo de prisão.', 'Motivo relevante documentado pode justificar alteração da pauta.', ['Presos têm preferência inicial? Sim.', 'Ordem é absolutamente inalterável? Não.'], 'Prioridade de pauta','Critérios legais de ordenação dos julgamentos.')
add(430,'Assistente precisa pedir habilitação até cinco dias antes da sessão em que pretende atuar.', ['Marco é sessão pretendida.', 'Não confundir com prazo do rol do art. 422.'], 'Habilitação tardia não se torna tempestiva por já haver interesse no resultado.', 'Ofendido requer habilitação com antecedência legal para atuar como assistente.', 'Pedido somente no dia da sessão não cumpre o prazo deste artigo.', ['Antecedência é de cinco dias? Sim.', 'Interesse dispensa requerimento no prazo? Não.'], 'Habilitação do assistente','Ingresso formal para atuação na sessão.')
add(431,'Processo em ordem exige intimação de partes, vítima se possível, testemunhas e peritos requeridos para plenário.', ['Observar art. 420 no que couber.', 'Peritos condicionados ao requerimento pertinente.'], 'Não confundir estar pautado com ter todos regularmente intimados.', 'Presidente providencia comunicações necessárias antes da sessão.', 'Laudo nos autos não significa perícia oral agendada sem requerimento.', ['Pauta substitui todas as intimações? Não.', 'Ofendido é intimado se possível? Sim.'], 'Convocação para plenário','Comunicação dos participantes do julgamento.')
add(432,'Depois de organizar pauta, juiz intima MP, OAB e Defensoria para acompanhar sorteio dos jurados.', ['Data e hora designadas.', 'Acompanhamento institucional do sorteio.'], 'Não confundir esta convocação com sorteio dos sete julgadores em plenário.', 'Instituições recebem ciência do sorteio para reunião periódica.', 'Presença das instituições não transforma todos os sorteados em Conselho do mesmo processo.', ['Defensoria integra os convocados? Sim.', 'É já o sorteio final do Conselho de sete? Não.'], 'Acompanhamento do sorteio','Fiscalização institucional da seleção para a reunião.')
add(433,'Sorteio público presidido pelo juiz seleciona vinte e cinco jurados para reunião periódica ou extraordinária.', ['Entre décimo quinto e décimo dia útil antes da instalação.', 'Ausência das partes não adia sorteio.', 'Não sorteado pode voltar a integrar seleção futura.'], 'Contar dias úteis e distinguir 25 convocados de sete do Conselho.', 'Juízo sorteia 25 a portas abertas no intervalo legal.', 'Parte ausente não impede o ato apenas por não comparecer.', ['Sorteio é a portas abertas? Sim.', 'Ausência de parte exige adiamento? Não.'], 'Sorteio da reunião','Seleção pública dos cidadãos convocáveis.')
add(434,'Sorteados são convocados por correio ou outro meio hábil, com data, hora e disposições legais.', ['Expediente transcreve arts. 436–446.', 'Forma deve ser apta à ciência.'], 'Convocação não pode ser presumida válida só porque nome consta de lista interna.', 'Jurado recebe comunicação idônea para comparecer.', 'Mensagem sem dados suficientes demanda verificar regularidade antes de sancionar falta.', ['Correio é o único meio permitido? Não.', 'Convocação deve conter as disposições indicadas? Sim.'], 'Meio hábil','Comunicação apta a informar o jurado.')
add(435,'Publicidade da reunião inclui jurados convocados, acusado, procuradores e data, hora e local das sessões.', ['Relação afixada no edifício do Tribunal do Júri.', 'Distinguir publicidade da pauta e intimação individual.'], 'Afixar lista não supre indiscriminadamente toda comunicação exigida nos outros artigos.', 'Quadro oficial informa sessão e participantes indicados.', 'Não concluir que jurado jamais comunicado faltou injustificadamente só pela lista.', ['Data, hora e local devem constar? Sim.', 'Publicidade substitui sempre intimação individual? Não.'], 'Publicidade da sessão','Informação oficial sobre convocados e julgamento.')
add(436,'Serviço do júri é obrigatório, com cidadãos maiores de dezoito anos de notória idoneidade e sem discriminação.', ['Não excluir por raça, cor, credo, sexo, profissão, classe, origem ou instrução.', 'Recusa injustificada: multa de um a dez salários mínimos conforme condição econômica.', 'Distinguir recusa injustificada de escusa legal e convicção do art. 438.'], 'Não exigir diploma superior ou condição econômica elevada para alistamento.', 'Pessoa idônea sem graduação pode integrar lista, observados requisitos legais.', 'Falta de diploma não é fundamento de exclusão; isenções próprias devem ser examinadas separadamente.', ['Graduação é requisito geral? Não.', 'Condição econômica influi na multa? Sim.'], 'Idoneidade e igualdade','Aptidão moral sem exclusões discriminatórias.')
add(437,'Isenções abrangem autoridades e funções enumeradas, militares ativos, maiores de setenta que peçam dispensa e justo impedimento.', ['Presidente/Ministros, Governadores/Secretários, parlamentares, prefeitos.', 'Magistrados, MP, Defensoria e servidores respectivos; polícia/segurança.', 'Militares em serviço ativo.', 'Maiores de setenta precisam requerer; justo impedimento deve ser demonstrado.'], 'Não ensinar dispensa automática de todo maior de setenta nem estender militar ativo a todo aposentado.', 'Pessoa maior de setenta requer dispensa na hipótese expressa.', 'Alegação genérica de compromisso exige demonstrar justo impedimento, não isenção presumida.', ['Maior de setenta deve requerer nessa hipótese? Sim.', 'Militar ativo é categoria expressa? Sim.'], 'Isenção do serviço','Hipóteses legais de dispensa da obrigação geral.')
add(438,'Recusa por convicção religiosa, filosófica ou política gera dever de serviço alternativo proporcional.', ['Atividades administrativas, assistenciais, filantrópicas ou produtivas nos órgãos/entidades indicados.', 'Juiz fixa com razoabilidade e proporcionalidade.', 'Não prestar serviço imposto tem consequência sobre direitos políticos prevista.'], 'Convicção não deve ser tratada como simples recusa injustificada sem analisar prestação alternativa.', 'Cidadão invoca convicção e recebe atividade alternativa adequada.', 'Cumprir serviço alternativo distingue-se de recusar também a obrigação substitutiva.', ['Convicção elimina toda obrigação? Não.', 'Serviço precisa ser proporcional? Sim.'], 'Escusa de consciência','Substituição da obrigação nos termos legais.')
add(439,'Exercício efetivo como jurado é serviço público relevante e estabelece presunção de idoneidade moral.', ['Redação atual decorre de Lei 12.403/2011.', 'Não recuperar antigo privilégio de prisão especial.', 'Exercício efetivo difere de mero alistamento.'], 'Não apresentar função como imunidade penal ou vantagem carcerária geral.', 'Certidão de efetivo exercício demonstra serviço público relevante.', 'Constar da lista sem exercer função não equivale automaticamente à condição exigida.', ['Artigo atual concede imunidade penal? Não.', 'Exercício precisa ser efetivo? Sim.'], 'Serviço público relevante','Reconhecimento do exercício real da função.')
add(440,'Jurado em efetivo exercício tem preferência em igualdade de condições nas hipóteses enumeradas.', ['Licitações; concurso para cargo/função pública; promoção ou remoção voluntária.', 'Exigir igualdade de condições e aplicação do regime pertinente.'], 'Não transformar desempate em aprovação garantida, pontos automáticos ou dispensa de requisitos.', 'Candidatos em igualdade pertinente têm critério de preferência analisado.', 'Nota inferior não se torna superior por ter sido jurado.', ['Preferência dispensa igualdade de condições? Não.', 'Garante aprovação sem requisitos? Não.'], 'Preferência legal','Vantagem condicionada à igualdade nas hipóteses previstas.')
add(441,'Sorteado que comparece à sessão não sofre desconto de vencimentos ou salário por essa participação.', ['Comparecimento é condição do texto.', 'Documentar participação para providências trabalhistas.'], 'Não estender automaticamente proteção a falta injustificada ou período estranho ao ato.', 'Empregado comprova comparecimento e salário não é descontado pela sessão.', 'Ausência sem comparecer exige análise diversa, não declaração fictícia de exercício.', ['Comparecimento é relevante? Sim.', 'Toda ausência ganha proteção automática? Não.'], 'Proteção remuneratória','Preservação da remuneração pela participação regular.')
add(442,'Falta sem causa legítima ou saída antes da dispensa leva a multa de um a dez salários mínimos segundo condição econômica.', ['Duas condutas: não comparecer e sair antes da liberação.', 'Examinar causa legítima.'], 'Não aplicar multa automática sem analisar motivo ou regularidade da convocação.', 'Jurado sai sem dispensa e sem causa legítima: examina-se sanção.', 'Emergência comprovada demanda avaliação antes de tratar ausência como injustificada.', ['Saída antes da dispensa pode ser sancionada? Sim.', 'Motivo legítimo deve ser examinado? Sim.'], 'Falta ao serviço','Ausência ou abandono sem causa legítima.')
add(443,'Escusa deve ter motivo relevante comprovado e ser apresentada até chamada, ressalvada força maior.', ['Comprovação exigida.', 'Exceção temporal para força maior.'], 'Não recusar toda justificativa posterior sem verificar força maior nem aceitar alegação vazia como prova.', 'Jurado comprova impedimento antes da chamada.', 'Emergência inevitável posterior exige exame da ressalva legal.', ['Motivo precisa ser comprovado? Sim.', 'Força maior admite ressalva ao marco temporal? Sim.'], 'Escusa comprovada','Justificação relevante da impossibilidade de servir.')
add(444,'Dispensa do jurado depende de decisão motivada do presidente, registrada na ata.', ['Não basta autorização informal sem documentação.', 'Examinar fundamento e registrar.'], 'Pedido de dispensa não equivale a decisão concedendo-a.', 'Juiz acolhe motivo comprovado e consigna dispensa na ata.', 'Jurado não deve presumir liberação apenas porque protocolou pedido.', ['Dispensa deve estar na ata? Sim.', 'Pedido sozinho é dispensa? Não.'], 'Dispensa formal','Decisão documentada e fundamentada.')
add(445,'Jurado responde criminalmente, no exercício ou a pretexto da função, nos termos aplicáveis ao juiz togado.', ['Responsabilidade exige enquadramento e prova.', 'Não confundir equiparação penal com todos os direitos funcionais de magistrado.'], 'Votar pela absolvição ou condenação não constitui crime por simples discordância externa com veredito.', 'Recebimento ilícito ligado à função exige apuração penal própria.', 'Resultado impopular não prova sozinho conduta criminosa do jurado.', ['Equiparação elimina necessidade de provar crime? Não.', 'Abrange conduta a pretexto da função? Sim.'], 'Responsabilidade funcional penal','Tratamento criminal da atuação relacionada à função.')
add(446,'Suplente convocado segue regras de dispensas, faltas, escusas e responsabilidade penal previstas.', ['Convocação é a condição expressa.', 'Não presumir ausência injustificada de suplente jamais convocado.'], 'Ser suplente na lista não equivale a receber toda convocação concreta.', 'Suplente convocado deve comparecer ou justificar regularmente.', 'Suplente não convocado não é sancionado como faltoso só pela lista.', ['Convocado segue regras de escusa? Sim.', 'Lista sozinha prova convocação concreta? Não.'], 'Suplente convocado','Substituto sujeito aos deveres pertinentes quando chamado.')
add(447,'Tribunal do Júri reúne presidente togado e vinte e cinco jurados sorteados; sete compõem Conselho em cada julgamento.', ['25 para composição convocada; sete julgadores da causa.', 'Juiz presidente não é um dos sete jurados.'], 'Não confundir 25 convocados com quórum de instalação de quinze do art. 463.', 'Dentre jurados aptos presentes sorteiam-se sete para julgar a causa.', 'Presidente dirige atos, mas não preenche um lugar do Conselho.', ['Conselho possui sete jurados? Sim.', 'Presidente integra esses sete? Não.'], 'Conselho de Sentença','Grupo de sete jurados que delibera no julgamento.')
add(448,'Relações familiares e convivência enumeradas impedem servir juntos no mesmo Conselho; jurados também seguem impedimentos e suspeições de juízes.', ['Casal/união estável, ascendente-descendente, sogro-genro/nora.', 'Irmãos/cunhados durante cunhadio, tio-sobrinho, padrasto/madrasta-enteado.', 'Aplicar demais incompatibilidades e suspeições pertinentes.'], 'Não reduzir regra somente a casamento formal nem tratar todo parentesco remoto como inciso expresso.', 'Companheiros em união estável reconhecida não servem juntos no Conselho.', 'Pessoa com relação não enumerada exige examinar eventual outro fundamento, sem inventar inciso.', ['União estável é abrangida? Sim.', 'Aplicam-se suspeições dos togados? Sim.'], 'Impedimento conjunto','Incompatibilidade de servir juntos por vínculo legal.')
add(449,'Não serve quem julgou antes o mesmo processo, julgou corréu no concurso de pessoas ou manifestou predisposição de condenar/absolver.', ['Julgamento anterior impede independentemente da causa do novo.', 'Predisposição exige atenção à imparcialidade.'], 'Não chamar novamente jurado do julgamento anulado só porque mudaram outros integrantes.', 'Jurado que participou do primeiro julgamento não integra novo Conselho do mesmo processo.', 'Manifestação antecipada de absolvição também impede, não só condenação.', ['Predisposição absolutória pode impedir? Sim.', 'Anulação permite reutilizar automaticamente mesmo jurado? Não.'], 'Imparcialidade do jurado','Ausência das experiências e predisposições impeditivas.')
add(450,'Entre jurados mutuamente impedidos por parentesco/convivência, serve quem foi sorteado primeiro.', ['Resolver impedimento entre os dois.', 'Não dispensar outros requisitos de aptidão.'], 'Sorteio primeiro não cura impedimento próprio contra o processo ou predisposição pessoal.', 'Dois irmãos são sorteados: prevalece o primeiro, se apto.', 'Primeiro também impedido por julgar antes a causa não se torna apto pelo art. 450.', ['Primeiro sorteado prevalece entre parentes aptos? Sim.', 'Isso elimina todo outro impedimento? Não.'], 'Precedência no sorteio','Critério para resolver incompatibilidade recíproca.')
assert len(rows)==26
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'jury organization units reviewed')
